const upsertSetup = `-- name: UpsertSetup :one
INSERT INTO mould_setups (workspace_id, mould_id, standard_cycle_s, active)
VALUES ($1, $2, ($3::text)::numeric, $4)
ON CONFLICT (workspace_id, mould_id) DO UPDATE SET standard_cycle_s = EXCLUDED.standard_cycle_s, active = EXCLUDED.active
RETURNING id
`

type UpsertSetupParams struct {
	WorkspaceID    pgtype.UUID `json:"workspace_id"`
	MouldID        pgtype.UUID `json:"mould_id"`
	StandardCycleS pgtype.Text `json:"standard_cycle_s"`
	Active         bool        `json:"active"`
}

func (q *Queries) UpsertSetup(ctx context.Context, arg UpsertSetupParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, upsertSetup,
		arg.WorkspaceID,
		arg.MouldID,
		arg.StandardCycleS,
		arg.Active,
	)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const userExists = `-- name: UserExists :one
SELECT EXISTS (SELECT 1 FROM users WHERE id = $1)::bool
`

func (q *Queries) UserExists(ctx context.Context, id pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, userExists, id)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
